// Une las pestañas leídas y arma una notificación por fila PENDIENTE (o reserva vencida).
// n8n solo escribe notificacion / notif_intentos / notif_reserva_hasta: no entran en el hash de /verificar.
const txt = (v) => String(v ?? '').trim();
const filas = (nodo) => $(nodo).all().map((i) => i.json)
  .filter((f) => f && Object.keys(f).some((k) => k !== 'row_number' && txt(f[k]) !== ''));
const activo = (v) => ['si', 'sí', 'true', 'verdadero', '1', 'x'].includes(txt(v).toLowerCase());
const esc = (v) => txt(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const fecha = (v) => { const t = Date.parse(txt(v)); return Number.isFinite(t)
  ? new Date(t).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'medium', timeStyle: 'short' }) : esc(v); };

const cfg = Object.fromEntries(filas('Leer CFG_General').map((f) => [txt(f.clave), txt(f.valor)]));
const URL_APP = (cfg.url_app || 'https://check-auditorio-web.vercel.app').replace(/\/+$/, '');
const MAX_INTENTOS = 3;
const RESERVA_MIN = Number(cfg.minutos_reserva_notificacion) || 90;
const ahora = Date.now();

// Destinatarios fijos de TODOS los eventos (recepción, devolución, novedad y alertas).
// CFG_Destinatarios suma otros sin tocar el flujo.
const DESTINATARIOS_FIJOS = [
  'rbracho@americana.edu.co',
  'andresbermudez@americana.edu.co',
  'auxdiradministrativa@americana.edu.co',
];
const destinatarios = filas('Leer CFG_Destinatarios').filter((f) => activo(f.activo) && txt(f.correo));
const correosDe = (...eventos) => [...new Set([...DESTINATARIOS_FIJOS, ...destinatarios
  .filter((d) => eventos.includes(txt(d.evento).toLowerCase())).map((d) => txt(d.correo).toLowerCase())])];
const alertaPara = correosDe('alerta', 'vencida');

const porId = (lista, clave) => Object.fromEntries(lista.map((f) => [txt(f[clave]), f]));
const agrupar = (lista) => lista.reduce((m, f) => ((m[txt(f.consecutivo)] ??= []).push(f), m), {});
const espacios = porId(filas('Leer CAT_Espacios'), 'id');
const asignaciones = porId(filas('Leer Asignaciones'), 'id');
const recepcionesLista = filas('Leer Recepciones');
const recepciones = porId(recepcionesLista, 'consecutivo');
const detRec = agrupar(filas('Leer Recepcion_Detalle'));
const detDev = agrupar(filas('Leer Devolucion_Detalle'));

const pendiente = (f) => {
  const estado = txt(f.notificacion).toUpperCase();
  const intentos = Number.parseInt(txt(f.notif_intentos), 10) || 0;
  if (intentos >= MAX_INTENTOS) return false;
  if (estado === 'PENDIENTE') return true;
  if (estado === 'ENVIANDO') { const hasta = Date.parse(txt(f.notif_reserva_hasta).split('|')[0]);
    return Number.isFinite(hasta) && hasta < ahora; }
  return false;
};

const ROL = { DOCENTE: 'Docente', ADMINISTRATIVO: 'Administrativo' };
const CATEGORIA = { EQUIPO: 'Equipos', MOBILIARIO: 'Mobiliario', ESPACIO: 'Condiciones del espacio' };
const RESULTADO = { BUENAS_CONDICIONES: 'En buenas condiciones', CON_NOVEDADES: 'Con novedades' };

const marco = (titulo, subtitulo, cuerpo) => '<!doctype html><html><body style="margin:0;padding:0;background:#f5f3ee;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f5f3ee;padding:24px 0;"><tr><td align="center">'
  + '<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border:1px solid #e3ded3;border-radius:8px;font-family:Arial,Helvetica,sans-serif;color:#1f2430;">'
  + '<tr><td style="background:#14264a;padding:20px 24px;border-radius:8px 8px 0 0;">'
  + '<div style="color:#d8b765;font-size:12px;letter-spacing:1px;text-transform:uppercase;">Infraestructura · Corporación Universitaria Americana</div>'
  + '<div style="color:#ffffff;font-size:20px;font-weight:bold;margin-top:6px;">' + esc(titulo) + '</div>'
  + '<div style="color:#c9d1e3;font-size:14px;margin-top:4px;">' + esc(subtitulo) + '</div></td></tr>'
  + '<tr><td style="padding:24px;">' + cuerpo + '</td></tr>'
  + '<tr><td style="padding:16px 24px;border-top:1px solid #e3ded3;color:#6b7080;font-size:12px;">'
  + 'Mensaje automático del sistema de entrega de espacios. La constancia oficial es el registro verificable en línea; este correo no la reemplaza.'
  + '</td></tr></table></td></tr></table></body></html>';

const fichas = (pares) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;margin-bottom:16px;">'
  + pares.filter(([, v]) => txt(v) !== '').map(([k, v]) => '<tr><td style="padding:4px 12px 4px 0;color:#6b7080;width:38%;vertical-align:top;">' + esc(k)
  + '</td><td style="padding:4px 0;vertical-align:top;">' + v + '</td></tr>').join('') + '</table>';

const boton = (texto, url) => '<p style="margin:20px 0;"><a href="' + esc(url) + '" style="background:#14264a;color:#ffffff;text-decoration:none;padding:10px 18px;border-radius:6px;font-size:14px;display:inline-block;">' + esc(texto) + '</a></p>';

const fotos = (ids) => txt(ids).split(',').filter(Boolean)
  .map((f, i) => '<a href="https://drive.google.com/file/d/' + encodeURIComponent(f) + '/view" style="color:#14264a;">foto ' + (i + 1) + '</a>').join(' · ');

const tablaDetalle = (det) => {
  const orden = [...det].sort((a, b) => txt(a.categoria).localeCompare(txt(b.categoria)) || txt(a.elemento_nombre).localeCompare(txt(b.elemento_nombre)));
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;border-collapse:collapse;">'
    + '<tr style="background:#f5f3ee;"><th align="left" style="padding:6px;border-bottom:1px solid #e3ded3;">Elemento</th><th align="left" style="padding:6px;border-bottom:1px solid #e3ded3;">Categoría</th>'
    + '<th align="right" style="padding:6px;border-bottom:1px solid #e3ded3;">Esperada</th><th align="right" style="padding:6px;border-bottom:1px solid #e3ded3;">Recibida</th>'
    + '<th align="left" style="padding:6px;border-bottom:1px solid #e3ded3;">Estado</th></tr>'
    + orden.map((d) => { const nov = txt(d.estado).toUpperCase() === 'NOVEDAD';
      return '<tr><td style="padding:6px;border-bottom:1px solid #eee;">' + esc(d.elemento_nombre)
        + (nov ? '<div style="color:#8a1c1c;font-size:12px;margin-top:2px;">' + esc(d.observacion) + (txt(d.foto_ids) ? ' — ' + fotos(d.foto_ids) : '') + '</div>' : '')
        + '</td><td style="padding:6px;border-bottom:1px solid #eee;">' + esc(CATEGORIA[txt(d.categoria)] ?? d.categoria)
        + '</td><td align="right" style="padding:6px;border-bottom:1px solid #eee;">' + esc(d.cantidad_esperada)
        + '</td><td align="right" style="padding:6px;border-bottom:1px solid #eee;">' + esc(d.cantidad_recibida)
        + '</td><td style="padding:6px;border-bottom:1px solid #eee;font-weight:bold;color:' + (nov ? '#8a1c1c' : '#1d6b3a') + ';">' + (nov ? 'Novedad' : 'Conforme') + '</td></tr>'; }).join('')
    + '</table>';
};

// Enlace de devolución: mecanismo pendiente de decisión (el token actual exige BETTER_AUTH_SECRET).
const enlaceDevolucion = (_asignacionId) => null;

const LIMITE_HTML = 95000; // Gmail recorta a partir de ~102 KB
const acotar = (html, respaldo) => (html.length > LIMITE_HTML ? respaldo : html);

const salida = [];

for (const r of recepcionesLista.filter(pendiente)) {
  const consecutivo = txt(r.consecutivo);
  const a = asignaciones[txt(r.asignacion_id)] ?? {};
  const e = espacios[txt(a.espacio_id)] ?? {};
  const det = detRec[consecutivo] ?? [];
  const hayNovedad = det.some((d) => txt(d.estado).toUpperCase() === 'NOVEDAD');
  const verificar = URL_APP + '/verificar/' + encodeURIComponent(consecutivo);
  const base = [
    ['Espacio', esc(e.nombre || a.espacio_id) + (txt(e.ubicacion) ? ' — ' + esc(e.ubicacion) : '')],
    ['Evento', esc(a.evento)],
    ['Franja', fecha(a.inicio) + ' → ' + fecha(a.fin)],
    ['Recibe', esc(r.receptor_nombre) + ' &lt;' + esc(r.receptor_correo) + '&gt;'],
    ['Rol', esc(ROL[txt(r.rol)] ?? r.rol)],
    ['Dependencia', esc(r.dependencia)],
    ['Cargo', esc(r.cargo)],
    ['Asistentes', esc(r.asistentes)],
    ['Sellada', fecha(r.sellada_en)],
    ['Código de verificación', '<strong>' + esc(r.codigo_verificacion) + '</strong>'],
  ];
  const resumen = hayNovedad
    ? '<p style="margin:0 0 16px;padding:10px 12px;background:#fbeaea;border-left:4px solid #8a1c1c;font-size:14px;">Se registraron <strong>novedades</strong> en la recepción.</p>'
    : '<p style="margin:0 0 16px;padding:10px 12px;background:#e9f4ed;border-left:4px solid #1d6b3a;font-size:14px;">Todos los elementos se recibieron conformes.</p>';
  const enlace = enlaceDevolucion(txt(r.asignacion_id));
  const bloqueDevolucion = enlace
    ? '<p style="font-size:14px;margin:16px 0 4px;">Al terminar, declara la devolución del espacio:</p>' + boton('Declarar devolución', enlace)
    : '<p style="font-size:14px;margin:16px 0 4px;">Al terminar, declara la devolución desde el enlace de tu pantalla de confirmación.</p>';
  const cuerpo = (conDevolucion) => resumen + fichas(base) + tablaDetalle(det) + boton('Verificar constancia', verificar) + (conDevolucion ? bloqueDevolucion : '');
  const cuerpoCorto = (conDevolucion) => resumen + fichas(base) + '<p style="font-size:14px;">El detalle completo está en la constancia en línea.</p>' + boton('Verificar constancia', verificar) + (conDevolucion ? bloqueDevolucion : '');
  const titulo = 'Constancia de recepción ' + consecutivo;
  const sub = (e.nombre || 'Espacio') + ' · ' + txt(a.evento);
  const fijos = correosDe('recepcion', ...(hayNovedad ? ['novedad'] : [])).filter((c) => c !== txt(r.receptor_correo).toLowerCase());
  salida.push({ json: {
    tipo: 'recepcion', hoja: 'Recepciones', consecutivo, reservaMinutos: RESERVA_MIN, alertaPara,
    receptor: { correo: txt(r.receptor_correo), nombre: txt(r.receptor_nombre),
      asunto: '[check-auditorio] ' + titulo + (hayNovedad ? ' (con novedades)' : ''),
      html: acotar(marco(titulo, sub, cuerpo(true)), marco(titulo, sub, cuerpoCorto(true))) },
    fijos: { para: fijos, asunto: '[check-auditorio] ' + titulo + (hayNovedad ? ' — NOVEDAD' : ''),
      html: acotar(marco(titulo, sub, cuerpo(false)), marco(titulo, sub, cuerpoCorto(false))) },
  } });
}

for (const d of filas('Leer Devoluciones').filter(pendiente)) {
  const consecutivo = txt(d.consecutivo);
  const r = recepciones[consecutivo] ?? {};
  const a = asignaciones[txt(r.asignacion_id)] ?? {};
  const e = espacios[txt(a.espacio_id)] ?? {};
  const nombres = Object.fromEntries((detRec[consecutivo] ?? []).map((x) => [txt(x.elemento_id), txt(x.elemento_nombre)]));
  const novedades = detDev[consecutivo] ?? [];
  const conNovedad = txt(d.resultado).toUpperCase() === 'CON_NOVEDADES';
  const verificar = URL_APP + '/verificar/' + encodeURIComponent(consecutivo);
  const listaNov = novedades.length
    ? '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;border-collapse:collapse;">'
      + novedades.map((x) => '<tr><td style="padding:6px;border-bottom:1px solid #eee;"><strong>' + esc(nombres[txt(x.elemento_id)] || x.elemento_id)
        + '</strong><div style="color:#8a1c1c;font-size:12px;margin-top:2px;">' + esc(x.observacion) + (txt(x.foto_ids) ? ' — ' + fotos(x.foto_ids) : '') + '</div></td></tr>').join('')
      + '</table>' : '';
  const cuerpo = (conNovedad
      ? '<p style="margin:0 0 16px;padding:10px 12px;background:#fbeaea;border-left:4px solid #8a1c1c;font-size:14px;">El espacio se devolvió <strong>con novedades</strong>.</p>'
      : '<p style="margin:0 0 16px;padding:10px 12px;background:#e9f4ed;border-left:4px solid #1d6b3a;font-size:14px;">El espacio se devolvió en buenas condiciones.</p>')
    + fichas([
      ['Constancia', esc(consecutivo)],
      ['Espacio', esc(e.nombre || a.espacio_id)],
      ['Evento', esc(a.evento)],
      ['Franja', fecha(a.inicio) + ' → ' + fecha(a.fin)],
      ['Declara', esc(r.receptor_nombre) + ' &lt;' + esc(r.receptor_correo) + '&gt;'],
      ['Resultado', esc(RESULTADO[txt(d.resultado)] ?? d.resultado)],
      ['Declarada', fecha(d.declarada_en)],
    ])
    + listaNov + boton('Ver constancia', verificar);
  const titulo = 'Devolución declarada ' + consecutivo;
  const sub = (e.nombre || 'Espacio') + ' · ' + txt(a.evento);
  const html = acotar(marco(titulo, sub, cuerpo), marco(titulo, sub, fichas([['Constancia', esc(consecutivo)]]) + boton('Ver constancia', verificar)));
  const fijos = correosDe('devolucion', ...(conNovedad ? ['novedad'] : [])).filter((c) => c !== txt(r.receptor_correo).toLowerCase());
  salida.push({ json: {
    tipo: 'devolucion', hoja: 'Devoluciones', consecutivo, reservaMinutos: RESERVA_MIN, alertaPara,
    receptor: { correo: txt(r.receptor_correo), nombre: txt(r.receptor_nombre),
      asunto: '[check-auditorio] ' + titulo + (conNovedad ? ' (con novedades)' : ''), html },
    fijos: { para: fijos, asunto: '[check-auditorio] ' + titulo + (conNovedad ? ' — NOVEDAD' : ''), html },
  } });
}

return salida;

// Relee la fila justo antes de reservar: otra ejecución pudo enviarla desde la lectura inicial.
const ctx = $('Recorrer pendientes').first().json;
const txt = (v) => String(v ?? '').trim();
const fila = $input.all().map((i) => i.json).find((f) => txt(f.consecutivo) === ctx.consecutivo);
const intentos = fila ? Number.parseInt(txt(fila.notif_intentos), 10) || 0 : 0;
let libre = false;
if (fila && intentos < 3) {
  const estado = txt(fila.notificacion).toUpperCase();
  const hasta = Date.parse(txt(fila.notif_reserva_hasta).split('|')[0]);
  libre = estado === 'PENDIENTE' || (estado === 'ENVIANDO' && Number.isFinite(hasta) && hasta < Date.now());
}
const vence = new Date(Date.now() + ctx.reservaMinutos * 60000 - 5 * 3600000).toISOString().slice(0, 19) + '-05:00';
return [{ json: { libre, intentos, reserva: vence + '|' + $execution.id } }];

// Sheets no tiene bloqueo: tras escribir la reserva se relee y solo envía quien quedó escrito.
const txt = (v) => String(v ?? '').trim();
const ctx = $('Recorrer pendientes').first().json;
const esperada = $('Decidir reserva').first().json.reserva;
const fila = $input.all().map((i) => i.json).find((f) => txt(f.consecutivo) === ctx.consecutivo);
const propia = !!fila && txt(fila.notificacion).toUpperCase() === 'ENVIANDO' && txt(fila.notif_reserva_hasta) === esperada;
return [{ json: { propia } }];

// Falló un envío de Gmail: +1 intento; al 3.º queda FALLIDO y se alerta a Infraestructura.
const ctx = $('Recorrer pendientes').first().json;
const txt = (v) => String(v ?? '').trim();
const esc = (v) => txt(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const intentos = $('Decidir reserva').first().json.intentos + 1;
const agotado = intentos >= 3;
const e = $input.first().json.error;
const mensaje = (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e ?? 'error desconocido')).slice(0, 500);
const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2430;">'
  + '<p><strong>No se pudo enviar la notificación de ' + esc(ctx.tipo) + ' ' + esc(ctx.consecutivo) + '</strong> después de ' + intentos + ' intentos.</p>'
  + '<p>Último error: <code>' + esc(mensaje) + '</code></p>'
  + '<p>La constancia está guardada en el libro; solo falló el correo. La fila quedó en <strong>FALLIDO</strong>: para reintentar, cambia <code>notificacion</code> a PENDIENTE y <code>notif_intentos</code> a 0.</p></div>';
return [{ json: {
  notificacion: agotado ? 'FALLIDO' : 'PENDIENTE', notif_intentos: String(intentos), agotado, mensaje,
  alertaPara: ctx.alertaPara.join(','), asunto: '[check-auditorio] Notificación FALLIDA ' + ctx.consecutivo, html,
} }];

// Falló la lectura o escritura del libro: nada se envió a medias; se alerta y la ejecución termina en error.
const txt = (v) => String(v ?? '').trim();
const esc = (v) => txt(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const e = $input.first()?.json?.error;
const mensaje = (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e ?? 'error desconocido')).slice(0, 800);
// Si el fallo ocurrió antes de armar el lote, se usan los fijos (mismos que en «Armar pendientes»).
let para = ['rbracho@americana.edu.co', 'andresbermudez@americana.edu.co', 'auxdiradministrativa@americana.edu.co'];
try { const p = $('Recorrer pendientes').first().json.alertaPara; if (Array.isArray(p) && p.length) para = p; } catch (_) {}
let consecutivo = '';
try { consecutivo = $('Recorrer pendientes').first().json.consecutivo; } catch (_) {}
const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2430;">'
  + '<p><strong>El flujo de notificaciones de check-auditorio falló</strong> en el nodo «' + esc($prevNode.name) + '»'
  + (consecutivo ? ' mientras procesaba ' + esc(consecutivo) : '') + '.</p>'
  + '<p>Error: <code>' + esc(mensaje) + '</code></p>'
  + '<p>Las constancias no se ven afectadas. Las filas pendientes se reintentan en la siguiente pasada (cada 15 min); una reserva a medias vence sola.</p>'
  + '<p>Ejecución n8n: ' + esc($execution.id) + '</p></div>';
return [{ json: { para: para.join(','), asunto: '[check-auditorio] Fallo técnico en notificaciones', html, mensaje } }];
